#!/usr/bin/env node
// Generates theme CSS variables and their typed map from src/theme/tokens.json.
// Usage: node scripts/generate-tokens.cjs [--check]
const { existsSync, readFileSync, writeFileSync } = require('node:fs')
const { join } = require('node:path')

const THEME_DIR = join(__dirname, '..', 'src', 'theme')
const TOKENS_PATH = join(THEME_DIR, 'tokens.json')
const OUTPUT_DIR = join(THEME_DIR, 'generated')
const HEADER =
  'Generated by frontend/scripts/generate-tokens.cjs from src/theme/tokens.json. Do not edit.'

function camelCase(name) {
  return name.replace(/-([a-z0-9])/g, (_match, letter) => letter.toUpperCase())
}

function themeColours(tokens, themeId) {
  return tokens.color.tokens.map((token) => [token.name, token.value[themeId]])
}

function themeShadow(tokens, themeId) {
  return tokens.shadow.tokens.map((token) => [token.name, token.value[themeId]])
}

// Families whose tokens are one value each, emitted as variables in this order.
const VALUE_FAMILIES = [
  'spacing',
  'radius',
  'duration',
  'easing',
  'zIndex',
  'breakpoint',
  'opacity',
  'size',
]

function typeStyles(tokens) {
  return tokens.type.groups.flatMap((group) =>
    group.styles.map((style) => ({ ...style, family: group.family })),
  )
}

// A letter spacing of 0 is no letter spacing; any other value marks an uppercase eyebrow.
function letterSpacing(style) {
  return style.letterSpacing && style.letterSpacing !== '0' ? style.letterSpacing : null
}

function typeProperties(style) {
  const prefix = `type-${style.name}`
  return [
    [`${prefix}-size`, style.fontSize],
    [`${prefix}-line-height`, style.lineHeight],
    [`${prefix}-weight`, String(style.fontWeight)],
    [`${prefix}-letter-spacing`, letterSpacing(style) ?? '0'],
  ]
}

function sharedProperties(tokens) {
  const families = Object.entries(tokens.type.families).map(([name, value]) => [
    `font-${name}`,
    value,
  ])
  const values = VALUE_FAMILIES.flatMap((family) =>
    tokens[family].tokens.map((token) => [token.name, token.value]),
  )

  return [...families, ...values, ...typeStyles(tokens).flatMap(typeProperties)]
}

function block(selector, scheme, properties) {
  const lines = properties.map(([name, value]) => `  --${name}: ${value};`)
  const schemeLine = scheme ? [`  color-scheme: ${scheme};`] : []

  return `${selector} {\n${[...schemeLine, ...lines].join('\n')}\n}\n`
}

function renderCss(tokens) {
  const light = [...themeColours(tokens, 'light'), ...themeShadow(tokens, 'light')]
  const dark = [...themeColours(tokens, 'dark'), ...themeShadow(tokens, 'dark')]

  return [
    `/* ${HEADER} */\n`,
    block(":root,\n[data-theme='light']", 'light', light),
    block("[data-theme='dark']", 'dark', dark),
    block(':root', null, sharedProperties(tokens)),
    // The stylesheet blocks first paint, so the ground is themed before the app renders.
    'html {\n  background-color: var(--bg);\n  color: var(--fg);\n}\n',
  ].join('\n')
}

function typeStyle(style, families) {
  const family = families[style.family]
  const parts = [
    `font-family: var(--font-${family});`,
    `font-size: ${style.fontSize};`,
    `line-height: ${style.lineHeight};`,
    `font-weight: ${style.fontWeight};`,
  ]
  if (letterSpacing(style)) {
    parts.push('text-transform: uppercase;', `letter-spacing: ${letterSpacing(style)};`)
  }

  return parts.join(' ')
}

function objectLiteral(entries, indent = '  ') {
  return entries.map(([key, value]) => `${indent}${key}: ${value},`).join('\n')
}

function quotedKey(name) {
  return /^[A-Za-z_$][\w$]*$/.test(name) ? name : `'${name}'`
}

function variableMap(names, keyFor) {
  return objectLiteral(names.map((name) => [keyFor(name), `'var(--${name})'`]))
}

function names(tokens, family, prefix) {
  return tokens[family].tokens.map((token) => token.name).filter((name) => name.startsWith(prefix))
}

// A typed map of one name prefix in a family: { short-name: 'var(--name)' }.
function prefixMap(tokens, family, prefix) {
  return variableMap(names(tokens, family, prefix), (name) =>
    quotedKey(camelCase(name.slice(prefix.length))),
  )
}

function typeVariables(style) {
  const [size, lineHeight, weight, spacing] = typeProperties(style).map(
    ([name]) => `'var(--${name})'`,
  )
  return `{ size: ${size}, lineHeight: ${lineHeight}, weight: ${weight}, letterSpacing: ${spacing} }`
}

function renderTs(tokens) {
  const colourNames = tokens.color.tokens.map((token) => token.name)
  const spaceNames = tokens.spacing.tokens.map((token) => token.name)
  const radiusNames = tokens.radius.tokens.map((token) => token.name)
  const styles = typeStyles(tokens)
  // Media queries cannot read custom properties, so breakpoints are raw pixel numbers.
  const breakpoints = tokens.breakpoint.tokens.map((token) => [
    quotedKey(token.name.replace('bp-', '')),
    String(parseInt(token.value, 10)),
  ])
  const families = { sans: 'sans', mono: 'mono' }
  const raw = (themeId) =>
    objectLiteral(
      themeColours(tokens, themeId).map(([name, value]) => [`'${name}'`, `'${value}'`]),
      '    ',
    )

  return `// ${HEADER}

export const color = {
${variableMap(colourNames, camelCase)}
} as const

export const space = {
${variableMap(spaceNames, (name) => `'${name.replace('space-', '')}'`)}
} as const

export const radius = {
${variableMap(radiusNames, (name) => quotedKey(name.replace('radius-', '')))}
} as const

export const duration = {
${prefixMap(tokens, 'duration', 'duration-')}
} as const

export const easing = {
${prefixMap(tokens, 'easing', 'ease-')}
} as const

export const zIndex = {
${prefixMap(tokens, 'zIndex', 'z-')}
} as const

export const breakpoint = {
${objectLiteral(breakpoints)}
} as const

export const opacity = {
${prefixMap(tokens, 'opacity', 'opacity-')}
} as const

export const size = {
${prefixMap(tokens, 'size', 'size-')}
} as const

export const icon = {
${prefixMap(tokens, 'size', 'icon-')}
} as const

export const ring = {
${prefixMap(tokens, 'size', 'ring-')}
} as const

export const offset = {
${prefixMap(tokens, 'size', 'offset-')}
} as const

export const pageWidth = {
${prefixMap(tokens, 'size', 'width-')}
} as const

export const font = {
  sans: 'var(--font-sans)',
  mono: 'var(--font-mono)',
} as const

export const shadow = 'var(--shadow)'

export const type = {
${objectLiteral(styles.map((style) => [quotedKey(camelCase(style.name)), `'${typeStyle(style, families)}'`]))}
} as const

// Each type style's parts, for a rule that matches one property of a style rather than all.
export const typeVar = {
${objectLiteral(styles.map((style) => [quotedKey(camelCase(style.name)), typeVariables(style)]))}
} as const

export const themeColours = {
  light: {
${raw('light')}
  },
  dark: {
${raw('dark')}
  },
} as const

export type ThemeId = keyof typeof themeColours
export type ColourToken = keyof (typeof themeColours)['light']
`
}

function outputs(tokens) {
  return { 'tokens.css': renderCss(tokens), 'tokens.ts': renderTs(tokens) }
}

function staleOutputs(tokens, directory = OUTPUT_DIR) {
  return Object.entries(outputs(tokens))
    .filter(([file, content]) => {
      const path = join(directory, file)
      return !existsSync(path) || readFileSync(path, 'utf8') !== content
    })
    .map(([file]) => file)
}

function writeOutputs(tokens, directory = OUTPUT_DIR) {
  for (const [file, content] of Object.entries(outputs(tokens))) {
    writeFileSync(join(directory, file), content)
  }
}

function main(argv) {
  const tokens = JSON.parse(readFileSync(TOKENS_PATH, 'utf8'))
  if (!argv.includes('--check')) {
    writeOutputs(tokens)
    return 0
  }
  const stale = staleOutputs(tokens)
  if (stale.length > 0) {
    console.error(
      `Generated theme files are stale: ${stale.join(', ')}. Run node frontend/scripts/generate-tokens.cjs.`,
    )
    return 1
  }

  return 0
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2))
}

module.exports = { renderCss, renderTs, staleOutputs, writeOutputs, TOKENS_PATH }
